    pub(super) fn render_card(
        &mut self,
        node: &CardNode,
        theme: &Theme,
        ds: &DesignSystem,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let mut element = div()
            .flex()
            .flex_col()
            .gap(px(ds.spacing.control_gap))
            .p(px(ds.spacing.card_padding))
            .bg(theme.surface)
            .rounded(px(ds.corners.md))
            .border_1()
            .border_color(theme.border);

        if let Some(title) = &node.title {
            element = element.child(
                div()
                    .text_size(px(ds.typography.large_size))
                    .font_weight(FontWeight::BOLD)
                    .text_color(theme.text_primary)
                    .child(title.clone()),
            );
        }

        apply_size(
            element.children(
                node.children
                    .iter()
                    .map(|child| self.render_node(child, theme, ds, cx)),
            ),
            node.width,
            node.height,
        )
        .into_any_element()
    }

    pub(super) fn render_button(
        &self,
        node: &ButtonNode,
        theme: &Theme,
        ds: &DesignSystem,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let bg = if node.selected {
            theme.accent
        } else {
            theme.surface_hover
        };
        let text = if node.disabled {
            theme.text_muted
        } else if node.selected {
            theme.text_on_accent
        } else {
            theme.text_primary
        };

        let element = div()
            .id(ElementId::Name(node.label.clone().into()))
            .px(px(ds.spacing.control_padding_x))
            .py(px(ds.spacing.control_padding_y))
            .rounded(px(ds.corners.md))
            .bg(bg)
            .text_color(text)
            .cursor_pointer()
            .child(node.label.clone());

        if node.disabled {
            return element.into_any_element();
        }

        if let Some(section_id) = node
            .action
            .as_deref()
            .and_then(|action| action.strip_prefix("select:"))
        {
            let section_id = section_id.to_string();
            return element
                .on_click(cx.listener(move |this, _, _window, cx| {
                    this.current_section = section_id.clone();
                    cx.notify();
                }))
                .into_any_element();
        }

        element.into_any_element()
    }

